/* Glossary: every highlighted term in the app comes from here.
   short  = one-line tooltip   long = beginner-friendly explanation
   domain = which Architect exam domain it shows up in (D1..D5)          */
window.CCA = window.CCA || {};
CCA.DOMAIN_NAMES = {
  D1: 'Agentic Architecture & Orchestration',
  D2: 'Tool Design & MCP Integration',
  D3: 'Claude Code Configuration & Workflows',
  D4: 'Prompt Engineering & Structured Output',
  D5: 'Context Management & Reliability',
};
CCA.GLOSSARY = {
  // ----------------------------------------------------------- basics
  'claude-code': {
    term: 'Claude Code', aliases: ['claude'], cat: 'Basics', domain: 'D3',
    short: "Anthropic's agentic coding tool: Claude working directly in your project from the terminal, IDE, desktop app or web.",
    long: 'Claude Code is an **agent** that lives where your code lives. Instead of copy-pasting code into a chat window, you start `claude` inside a project folder and describe what you want. Claude can read files, search the codebase, run commands, edit files and make git commits, asking your permission for anything risky. It runs in the terminal (CLI), in VS Code and JetBrains, in the Claude desktop app, and on the web at claude.ai/code.',
    example: 'cd my-project\nclaude', analogy: 'a very fast junior developer sitting at your keyboard, who always asks before touching anything important.',
  },
  terminal: {
    term: 'Terminal', aliases: ['shell', 'command line', 'cli'], cat: 'Basics',
    short: 'A text window where you type commands for your computer instead of clicking.',
    long: 'The terminal (also called the shell or command line) is a program where you type commands and press Enter. On Windows it is **PowerShell** or **Windows Terminal**; on macOS it is **Terminal**. Claude Code\'s classic interface runs inside a terminal.',
    example: 'cd Documents      # change directory\nls                # list files (dir on old Windows shells)',
    analogy: 'texting your computer instead of tapping on its screen.',
  },
  cd: { term: 'cd (change directory)', aliases: ['cd'], cat: 'Basics', short: 'Moves your terminal into a different folder.', long: '`cd folder-name` moves the terminal into that folder. Claude Code works on whatever folder you start it in, so you always `cd` into your project first. `cd ..` goes up one level.', example: 'cd my-project' },
  repo: { term: 'Repository (repo)', aliases: ['repository', 'git repo'], cat: 'Basics', short: 'A project folder tracked by git, so every change has history.', long: 'A repository is a project folder whose history is tracked by **git**. Claude Code works best in a git repo because you can always see (`git diff`) and undo (`git checkout`) what changed.' },
  git: { term: 'Git', cat: 'Basics', short: 'Version control: it records snapshots (commits) of your project so you can review and undo changes.', long: 'Git saves snapshots of your project called **commits**. Claude Code can run git for you: write commit messages, create branches, resolve merge conflicts and open pull requests (with the GitHub CLI).', example: 'git status\ngit diff\ngit commit -m "Fix login bug"' },
  token: { term: 'Token', aliases: ['tokens'], cat: 'Basics', domain: 'D5', short: 'The unit Claude reads and writes text in; roughly ¾ of a word.', long: 'Models read and write text in small pieces called **tokens** (about 3–4 characters each). Context windows, prices and limits are all measured in tokens. Every file Claude reads uses up tokens in its context window.' },
  'context-window': {
    term: 'Context window', aliases: ['context windows'], cat: 'Context', domain: 'D5',
    short: "Claude's working memory for one conversation: everything it can see at once.",
    long: 'The context window holds everything Claude can "see" right now: the system prompt, CLAUDE.md, your messages, every file it read, every command output. It is large but not infinite. When it fills up, older details get summarized (**compaction**) and quality can drop. Good Claude Code users keep context focused: `/clear` between unrelated tasks, use subagents for big searches, and point Claude at specific files.',
    analogy: 'a desk: you can only spread out so many papers before you need to file some away.',
  },
  model: { term: 'Model', aliases: ['models', 'opus', 'sonnet', 'haiku'], cat: 'Basics', short: 'The AI brain Claude Code uses: e.g. Opus (most capable), Sonnet (balanced), Haiku (fast and cheap).', long: 'Claude comes in model families. **Opus** is the most capable of the main line, **Sonnet** balances speed and capability, and **Haiku** is fastest and cheapest. Switch in Claude Code with `/model`. Subagents can use a cheaper model for simple jobs.', example: '/model' },
  agent: { term: 'Agent', aliases: ['agentic', 'ai agent'], cat: 'Agents', domain: 'D1', short: 'An AI that works in a loop: it decides on actions (tool calls), sees the results, and keeps going until the task is done.', long: 'A plain chatbot answers once. An **agent** works in a loop: think → call a tool (read a file, run tests) → look at the result → decide the next step, until the goal is met. Claude Code is an agent. The Architect exam is largely about designing agents well.', analogy: 'the difference between asking for directions and hiring someone to drive you there.' },
  'agentic-loop': {
    term: 'Agentic loop', aliases: ['agent loop', 'tool loop'], cat: 'Agents', domain: 'D1',
    short: 'The cycle: send messages → Claude replies with tool_use → you run the tool → send tool_result → repeat until stop_reason is end_turn.',
    long: 'Under the hood every agent runs the same loop. Your code sends the conversation to the API. If the response has `stop_reason: "tool_use"`, you run the requested tool and send the result back as a `tool_result`. When `stop_reason` is `"end_turn"`, Claude is done. **Exam tip:** loop on `stop_reason`, not on whether the reply contains text, and don\'t rely on arbitrary iteration caps as the main stop condition.',
    example: 'while True:\n    resp = client.messages.create(...)\n    if resp.stop_reason != "tool_use":\n        break\n    results = run_tools(resp.content)\n    messages += [assistant(resp), user(results)]', lang: 'python',
  },
  'stop-reason': { term: 'stop_reason', aliases: ['stop reason', 'end_turn', 'tool_use stop'], cat: 'API', domain: 'D1', short: 'Field in every API response saying why Claude stopped: end_turn, tool_use, max_tokens, pause_turn, refusal…', long: '`stop_reason` tells your code what to do next: `tool_use` = run the tool and continue; `end_turn` = finished; `max_tokens` = cut off (raise the limit or continue); `pause_turn` = a long server-tool turn paused, send it back to resume; `refusal` = declined for safety.' },
  prompt: { term: 'Prompt', cat: 'Prompting', domain: 'D4', short: 'The instructions and context you give Claude.', long: 'Your prompt is what you type. In Claude Code, good prompts are **specific** (which file, which behavior), give **context** (why, constraints), and say **how to verify** ("run the tests after"). Vague: "fix the bug". Better: "Users get a 500 error on /login when the email has a + sign. Find the cause in src/auth, fix it, and add a test."' },
  'system-prompt': { term: 'System prompt', aliases: ['system message', '--append-system-prompt'], cat: 'Prompting', domain: 'D4', short: 'Behind-the-scenes instructions that set the role and rules for the whole conversation.', long: 'The system prompt is sent before the conversation and shapes all of Claude\'s behavior. Claude Code has its own built-in system prompt; your CLAUDE.md is added as context, and in headless mode you can add more with `--append-system-prompt`.' },
  hallucination: { term: 'Hallucination', cat: 'Prompting', domain: 'D5', short: 'When a model states something false with confidence.', long: 'Models can produce plausible but wrong details (an API that does not exist, a made-up citation). Reduce it by giving Claude the real source (files, docs), asking it to quote evidence, letting it say "I don\'t know", and verifying with tests.' },

  // ------------------------------------------------- Claude Code features
  'claude-md': {
    term: 'CLAUDE.md', aliases: ['claude.md', 'memory file', 'project memory'], cat: 'Memory', domain: 'D3',
    short: 'A Markdown file Claude Code automatically reads at startup: your project\'s standing instructions.',
    long: 'CLAUDE.md is **memory**: instructions Claude loads into context every session. Put build/test commands, code style, architecture notes and "gotchas" here. Locations form a hierarchy: **user** (`~/.claude/CLAUDE.md`, all your projects), **project** (`./CLAUDE.md`, shared with your team via git), and files in subfolders that load when Claude works there. Organizations can also deploy a managed policy file. Keep it short and specific; it costs tokens every session. You can import other files with `@path/to/file`.',
    example: '# Project: Shop API\n## Commands\n- Test: npm test\n- Lint: npm run lint\n## Style\n- TypeScript strict, no `any`\n- Use async/await, never .then()\n## Gotchas\n- Never edit generated files in src/gen/', lang: 'md',
    analogy: 'the sticky note on your monitor that every new teammate reads on day one.',
  },
  'memory-hierarchy': { term: 'Memory hierarchy', aliases: ['claude.md hierarchy', 'memory scopes'], cat: 'Memory', domain: 'D3', short: 'Managed policy → user (~/.claude/CLAUDE.md) → project (./CLAUDE.md) → subfolder CLAUDE.md files.', long: 'Claude Code loads memory from several places. **Managed policy** (set by your organization) applies to everyone. **User memory** `~/.claude/CLAUDE.md` is personal and applies to every project; it is NOT shared with teammates. **Project memory** `./CLAUDE.md` (or `./.claude/CLAUDE.md`) is committed to git and shared. **Subdirectory** CLAUDE.md files load when Claude works in that folder. **Exam trap:** if a teammate isn\'t getting an instruction, check whether it lives in someone\'s *user* memory instead of the project file.' },
  rules: { term: '.claude/rules/', aliases: ['rules', 'path-specific rules', 'rules directory'], cat: 'Memory', domain: 'D3', short: 'A folder of topic-specific instruction files; with a `paths:` glob in frontmatter they only load for matching files.', long: 'Instead of one giant CLAUDE.md, you can split instructions into `.claude/rules/*.md` files (e.g. `testing.md`, `api-style.md`). Add YAML frontmatter with `paths:` globs (like `**/*.test.ts`) so a rule only loads when Claude works on matching files. Great for conventions that apply to a *type* of file spread across many folders.', example: '---\npaths:\n  - "**/*.test.ts"\n---\n# Test conventions\n- Use describe/it blocks\n- Mock the network with msw', lang: 'md' },
  import: { term: '@ imports', aliases: ['@import', 'claude.md imports'], cat: 'Memory', domain: 'D3', short: 'Write @path/to/file inside CLAUDE.md to pull another file into memory.', long: 'CLAUDE.md can include other files with `@path` (e.g. `@docs/architecture.md`, `@package.json`). This keeps CLAUDE.md small and modular.' },
  'slash-command': {
    term: 'Slash command', aliases: ['slash commands', '/command'], cat: 'Commands', domain: 'D3',
    short: 'A command starting with / typed inside Claude Code, e.g. /init, /clear, /compact, /model.',
    long: 'Slash commands control the session. **Built-in** ones include `/help`, `/init`, `/clear`, `/compact`, `/context`, `/cost`, `/model`, `/permissions`, `/memory`, `/agents`, `/mcp`, `/hooks`, `/resume`, `/rewind`. You can also write **custom** commands as Markdown files: `.claude/commands/name.md` (shared with your project) or `~/.claude/commands/name.md` (personal, all projects). Custom commands and **skills** share the same system: a skill can also be run as `/skill-name`.',
  },
  'custom-command': { term: 'Custom slash command', aliases: ['.claude/commands', 'project command', 'commands folder'], cat: 'Commands', domain: 'D3', short: 'A reusable prompt saved as .claude/commands/<name>.md and run as /<name>.', long: 'Save a prompt you use often as a Markdown file. `$ARGUMENTS` is replaced with whatever you type after the command (`$1`, `$2` for positional args). Optional frontmatter sets `description`, `argument-hint`, `allowed-tools` and `model`. Project commands (`.claude/commands/`) are shared via git; personal ones live in `~/.claude/commands/`.', example: '---\ndescription: Review a file for bugs\nargument-hint: <file>\nallowed-tools: Read, Grep\n---\nReview $ARGUMENTS for bugs, security issues and\nmissing tests. Report findings as a numbered list.', lang: 'md' },
  arguments: { term: '$ARGUMENTS', aliases: ['$arguments', '$1'], cat: 'Commands', domain: 'D3', short: 'Placeholder in a custom command replaced by whatever you type after it.', long: 'In `.claude/commands/fix-issue.md`, writing `Fix GitHub issue #$ARGUMENTS` means `/fix-issue 42` becomes "Fix GitHub issue #42". `$1`, `$2` give individual positional arguments.' },
  skill: {
    term: 'Skill', aliases: ['skills', 'agent skills', 'skill.md'], cat: 'Extending', domain: 'D3',
    short: 'A folder with a SKILL.md (name + description + instructions, plus optional scripts) that Claude loads only when relevant.',
    long: 'A **skill** packages know-how: `.claude/skills/<name>/SKILL.md` with YAML frontmatter (`name`, `description`) and instructions, plus any scripts or templates. Only the short description sits in context until Claude decides the skill is relevant (or you run `/name`); then the full instructions load. This is **progressive disclosure**: lots of capability, little context cost. Frontmatter can set `allowed-tools`, and `context: fork` to run the skill in an isolated subagent so its verbose work doesn\'t clutter the main conversation.',
    example: '---\nname: release-notes\ndescription: Write release notes from merged PRs. Use when the user asks for a changelog or release notes.\n---\n1. Run `git log --oneline v1.2.0..HEAD`\n2. Group changes into Features / Fixes / Chores\n3. Write RELEASE_NOTES.md in plain English', lang: 'md',
    analogy: 'a recipe card in a drawer: you only pull it out when you are cooking that dish.',
  },
  'progressive-disclosure': { term: 'Progressive disclosure', cat: 'Extending', domain: 'D5', short: 'Load only a short summary up front; pull in full detail only when it is needed.', long: 'Skills, deferred MCP tools and tool search all use progressive disclosure to keep the context window lean: Claude sees names and descriptions first and loads the details on demand.' },
  subagent: {
    term: 'Subagent', aliases: ['subagents', 'sub-agent', '.claude/agents', 'task tool', 'agent tool'], cat: 'Agents', domain: 'D1',
    short: 'A helper Claude with its own fresh context window, its own instructions and tool list, that the main Claude delegates a task to.',
    long: 'Subagents are defined as Markdown files in `.claude/agents/` (project) or `~/.claude/agents/` (user), or created with `/agents`. Frontmatter sets `name`, `description` (when to use it), `tools` (allowed tools) and `model`. The main agent delegates via the Agent (formerly Task) tool. The subagent works in **its own context window** and returns only a summary, so big searches don\'t flood the main conversation. **Key exam point:** subagents do NOT automatically inherit the parent\'s conversation. Pass everything they need explicitly in the task prompt.',
    example: '---\nname: code-reviewer\ndescription: Expert code reviewer. Use right after code changes.\ntools: Read, Grep, Glob\nmodel: sonnet\n---\nYou are a senior reviewer. Check for bugs, security\nissues and missing tests. Be specific; cite file:line.', lang: 'md',
    analogy: 'sending an intern to the library with a clear brief; they come back with a one-page summary instead of the whole stack of books.',
  },
  'hub-and-spoke': { term: 'Coordinator / hub-and-spoke', aliases: ['coordinator', 'orchestrator', 'orchestrator-worker', 'hub and spoke'], cat: 'Agents', domain: 'D1', short: 'One coordinator agent splits the work, sends pieces to specialist subagents, and combines their results.', long: 'In a multi-agent system the **coordinator** plans, delegates to **subagents** (spokes), collects their outputs and synthesizes. Subagents talk only to the coordinator, which keeps control flow observable and error handling in one place. Watch for: overly narrow task decomposition (missing topics), and passing too little context to subagents.' },
  'context-isolation': { term: 'Context isolation', cat: 'Agents', domain: 'D1', short: 'Each subagent starts with a clean context; it sees only what you pass it.', long: 'Isolation is both a feature (no clutter, focused work, parallelism) and a trap (the subagent doesn\'t know what the coordinator learned). Pass relevant findings, constraints and source metadata explicitly.' },
  hook: {
    term: 'Hook', aliases: ['hooks', 'pretooluse', 'posttooluse', 'pre tool use', 'post tool use'], cat: 'Extending', domain: 'D1',
    short: 'A shell command Claude Code runs automatically at a lifecycle event (e.g. before/after a tool call). Deterministic, not up to the model.',
    long: 'Hooks are configured in settings.json. Events include **PreToolUse** (before a tool runs; can block it), **PostToolUse** (after; e.g. run a formatter), **UserPromptSubmit**, **Stop**, **SubagentStop**, **SessionStart**, **SessionEnd**, **PreCompact**, **Notification**. A `matcher` picks which tools (e.g. `Edit|Write`). A PreToolUse hook that exits with **code 2** blocks the call, and its stderr is shown to Claude. **Exam favorite:** if a rule *must* always hold (compliance, never touch prod, refund limits), enforce it with a hook. Instructions in a prompt are only *probabilistic*.',
    example: '{\n  "hooks": {\n    "PostToolUse": [\n      {\n        "matcher": "Edit|Write",\n        "hooks": [{ "type": "command", "command": "npx prettier --write \\"$CLAUDE_PROJECT_DIR\\"" }]\n      }\n    ]\n  }\n}', lang: 'json',
    analogy: 'a seatbelt chime: it goes off every time, no matter what the driver intends.',
  },
  'exit-code-2': { term: 'Exit code 2 (hooks)', aliases: ['exit 2'], cat: 'Extending', domain: 'D1', short: 'When a PreToolUse hook exits with 2, Claude Code blocks the tool call and feeds the hook\'s stderr back to Claude.', long: 'Exit 0 = OK (continue). Exit 2 = blocking error: the action is stopped and the message on stderr goes to Claude so it can adjust. Other non-zero codes are non-blocking errors shown to the user. Hooks can also print JSON for finer control (e.g. a permission decision).' },
  mcp: {
    term: 'MCP (Model Context Protocol)', aliases: ['mcp', 'model context protocol', 'mcp server', 'mcp servers'], cat: 'Extending', domain: 'D2',
    short: 'An open standard for plugging tools and data sources (GitHub, databases, Slack, Jira…) into Claude.',
    long: 'MCP is like **USB-C for AI**: any app that speaks MCP can connect to any MCP **server**. A server exposes **tools** (actions), **resources** (readable data) and **prompts**. In Claude Code add one with `claude mcp add`; check status with `/mcp`. Servers run locally (**stdio** transport) or remotely (**HTTP**; SSE is the older remote transport). MCP tools appear to Claude with names like `mcp__github__create_issue`.',
    example: '# remote server over HTTP\nclaude mcp add --transport http notion https://mcp.notion.com/mcp\n\n# local server over stdio, shared with the team\nclaude mcp add --scope project db -- npx -y @bytebase/dbhub --dsn "$DB_URL"',
    analogy: 'a universal power strip: one standard socket, any appliance.',
  },
  'mcp-scope': { term: 'MCP scopes', aliases: ['.mcp.json', 'mcp scope', 'local scope', 'project scope', 'user scope'], cat: 'Extending', domain: 'D2', short: 'local (just you, this project) · project (.mcp.json, shared via git) · user (you, every project).', long: '`--scope local` (the default) stores the server privately for you in this project. `--scope project` writes `.mcp.json` at the repo root so the whole team gets it via git (Claude Code asks each person to approve project servers). `--scope user` makes it available to you in all projects. Keep secrets out of `.mcp.json`: use environment-variable expansion like `${GITHUB_TOKEN}`.', example: '{\n  "mcpServers": {\n    "github": {\n      "type": "http",\n      "url": "https://api.githubcopilot.com/mcp/",\n      "headers": { "Authorization": "Bearer ${GITHUB_TOKEN}" }\n    }\n  }\n}', lang: 'json' },
  'mcp-resource': { term: 'MCP resource', aliases: ['resources'], cat: 'Extending', domain: 'D2', short: 'Read-only data an MCP server exposes (a doc, a schema, a ticket) that you can @-mention.', long: 'Tools *do* things; resources are things to *read*. Exposing a content catalog as resources lets Claude see what exists without many exploratory tool calls. In Claude Code you reference them like `@server:resource-uri`.' },
  tool: { term: 'Tool', aliases: ['tools', 'tool use', 'function calling', 'tool_use'], cat: 'Tools', domain: 'D2', short: 'An action Claude can request: read a file, run a command, call an API. Your code (or Claude Code) actually runs it.', long: 'A tool has a **name**, a **description** and an **input schema** (JSON Schema). Claude chooses tools mostly from their descriptions, so clear descriptions (what it does, when to use it, what inputs look like, edge cases) are the #1 lever for correct tool selection. Claude Code\'s built-in tools include Read, Write, Edit, Bash, Grep, Glob, WebFetch, WebSearch and the Agent tool.' },
  'tool-description': { term: 'Tool description', aliases: ['tool descriptions'], cat: 'Tools', domain: 'D2', short: 'The text that tells Claude what a tool does and when to use it; the main thing Claude uses to choose between tools.', long: 'If two tools have vague, overlapping descriptions ("Retrieves customer information" vs "Retrieves order details"), Claude will mix them up. Fix it by making the descriptions say when to use each, what the inputs look like, and how the tool differs from similar ones. Renaming or splitting overlapping tools also helps. This is usually the first and cheapest fix, before routing layers or few-shot examples.' },
  'tool-choice': { term: 'tool_choice', aliases: ['tool choice', 'forced tool'], cat: 'Tools', domain: 'D2', short: 'API setting: auto (Claude decides), any (must use some tool), a specific tool, or none.', long: '`auto` lets Claude answer in text or call a tool. `any` forces some tool call; `{"type":"tool","name":"x"}` forces one tool, the classic way to guarantee structured output. `none` disables tools. **Heads-up:** some of the newest models (e.g. Claude Opus 5.5) reject the forced `any`/`tool` options. There you use `auto` + `strict: true` tools or structured outputs instead. The exam tests the concept; check current docs for model support.' },
  'structured-error': { term: 'Structured tool errors', aliases: ['iserror', 'is_error', 'error response'], cat: 'Tools', domain: 'D2', short: 'Return errors from tools with is_error plus useful details (category, retryable?, message) instead of a bare "failed".', long: 'Good tool errors help the agent recover: say whether it was a **transient** problem (timeout; retry), a **validation** error (fix the input), a **business-rule** violation (explain to the user), or a **permission** issue. Distinguish "the query failed" from "the query succeeded and found nothing". Silently returning empty results as success is a classic anti-pattern.' },
  'structured-output': { term: 'Structured output', aliases: ['json schema', 'structured outputs', 'json output'], cat: 'Prompting', domain: 'D4', short: 'Getting Claude to return data in an exact format (usually JSON matching a schema).', long: 'Most reliable: define the format as a **JSON schema**, via a tool\'s `input_schema` or the API\'s structured outputs (`output_config.format`). This guarantees *syntax*, but not *semantics*: values can still be wrong, so validate and retry with the error message. Make fields **nullable/optional** when the source may not have the info, so Claude doesn\'t invent values.' },
  'few-shot': { term: 'Few-shot examples', aliases: ['few shot', 'examples', 'multishot'], cat: 'Prompting', domain: 'D4', short: 'Showing Claude 2–5 worked examples of input → desired output inside the prompt.', long: 'Examples are the most effective way to pin down format and judgment on ambiguous cases. Pick examples that show *why* one answer is right, cover edge cases, and vary enough that Claude generalizes rather than copying.' },
  'explicit-criteria': { term: 'Explicit criteria', cat: 'Prompting', domain: 'D4', short: 'Spell out exactly what counts (and doesn\'t count) instead of saying "be conservative".', long: 'Vague instructions like "only report high-confidence issues" don\'t reduce false positives much. Concrete criteria do: "Report only: SQL injection, missing auth checks, unhandled promise rejections. Skip: style, naming, minor perf."' },
  'validation-retry': { term: 'Validation-retry loop', aliases: ['retry with error'], cat: 'Prompting', domain: 'D4', short: 'Check Claude\'s output; if invalid, send it back WITH the specific error so it can fix it.', long: 'Retrying blindly rarely helps; retrying with the exact validation error ("total 120 ≠ sum of line items 115") usually does. But retries can\'t fix information that is simply absent from the source; that should become null/"not found".' },
  'batch-api': { term: 'Message Batches API', aliases: ['batch', 'batches', 'batch api'], cat: 'API', domain: 'D4', short: 'Send many requests at once, asynchronously, for about 50% lower cost; results within 24 hours.', long: 'Great for non-urgent bulk jobs (overnight reports, classifying 10,000 docs). Not for anything a person or a blocking CI check is waiting on, since there\'s no latency guarantee. Results come back in any order; match them by `custom_id`.' },
  'prompt-caching': { term: 'Prompt caching', aliases: ['cache', 'caching', 'cache_control'], cat: 'API', domain: 'D5', short: 'Reusing an unchanged prompt prefix across requests so it is much cheaper and faster.', long: 'Mark a stable prefix (system prompt, big document, tool list) with `cache_control`. Later requests with the identical prefix read it from cache at ~10% of the price. Any byte change in the prefix breaks the cache, so put changing content last.' },
  'permission-mode': {
    term: 'Permission modes', aliases: ['permission mode', 'default mode', 'accept edits', 'acceptedits', 'bypasspermissions', 'auto mode'], cat: 'Permissions', domain: 'D3',
    short: 'How much Claude may do without asking: default (asks), acceptEdits (auto-accepts file edits), plan (read-only), and more autonomous modes.',
    long: '**default**: asks before edits and commands. **acceptEdits**: file edits go through automatically; commands still ask. **plan**: read-only research and planning, no changes. Newer versions add an **auto** mode where a safety check decides what needs your OK. **bypassPermissions** (`--dangerously-skip-permissions`) skips all prompts, only safe in an isolated sandbox/container. Press <kbd>Shift</kbd>+<kbd>Tab</kbd> to cycle modes.',
  },
  'plan-mode': { term: 'Plan mode', aliases: ['plan'], cat: 'Permissions', domain: 'D3', short: 'Read-only mode: Claude researches and proposes a plan, changing nothing until you approve.', long: 'Use plan mode for big, ambiguous or risky work: multi-file refactors, architecture decisions, unfamiliar codebases. Claude explores, then presents a plan; you approve or edit it before any change. For a clear one-line fix, plan mode is overkill: just do it. Toggle with <kbd>Shift</kbd>+<kbd>Tab</kbd> (twice from default).', analogy: 'an architect\'s blueprint before the builders arrive.' },
  'permission-rules': { term: 'Permission rules', aliases: ['allow', 'deny', 'allowedtools', '--allowedtools', 'permissions'], cat: 'Permissions', domain: 'D3', short: 'allow / ask / deny lists in settings.json, e.g. allow "Bash(npm test:*)", deny "Read(./.env)".', long: 'Rules pre-approve or forbid specific tool uses so you aren\'t asked every time. Format: `Tool` or `Tool(specifier)`. Deny beats allow. Manage interactively with `/permissions`, or pass `--allowedTools` on the command line (common in CI).', example: '{\n  "permissions": {\n    "allow": ["Bash(npm run test:*)", "Bash(git diff:*)", "Read(./src/**)"],\n    "deny":  ["Read(./.env)", "Bash(rm -rf:*)", "WebFetch"]\n  }\n}', lang: 'json' },
  settings: { term: 'settings.json', aliases: ['settings', 'settings.local.json', '.claude/settings.json'], cat: 'Config', domain: 'D3', short: 'Claude Code\'s config files: user (~/.claude/settings.json), project (.claude/settings.json), local (.claude/settings.local.json), plus managed policy.', long: 'Settings hold permissions, hooks, environment variables, the default model and more. **Precedence (highest first):** managed policy → command-line flags → local project (`.claude/settings.local.json`, git-ignored, just you) → shared project (`.claude/settings.json`, committed) → user (`~/.claude/settings.json`). Use `/config` to change many settings interactively.' },
  'dot-claude': { term: '.claude/ folder', aliases: ['.claude', '.claude folder'], cat: 'Config', domain: 'D3', short: 'The project folder holding Claude Code config: settings.json, commands/, agents/, skills/, rules/, hooks scripts.', long: 'Commit `.claude/` (except `settings.local.json`) so the whole team shares the same commands, subagents, skills, rules and permissions. Your personal equivalents live in `~/.claude/`.' },
  checkpoint: { term: 'Checkpoints & /rewind', aliases: ['rewind', '/rewind', 'checkpoints', 'esc esc'], cat: 'Session', domain: 'D3', short: 'Claude Code snapshots file edits as you go; /rewind (or Esc Esc) jumps back.', long: 'Every prompt creates a checkpoint. `/rewind` (or pressing <kbd>Esc</kbd> twice) lets you restore the code, the conversation, or both to an earlier point. Changes made by shell commands (like `rm` or database migrations) aren\'t tracked, so git is still your real safety net.' },
  compact: { term: '/compact', aliases: ['compaction', 'auto-compact', 'compact'], cat: 'Context', domain: 'D5', short: 'Summarizes the conversation so far to free up context, optionally with focus instructions.', long: 'When context gets full, Claude Code auto-compacts. You can do it yourself at a good moment: `/compact keep the API design decisions and the failing test names`. Summaries lose detail (exact numbers, IDs, dates), so keep critical facts in a file or CLAUDE.md, or in a "case facts" block that you always carry forward.' },
  clear: { term: '/clear', cat: 'Context', domain: 'D5', short: 'Wipes the conversation and starts fresh (CLAUDE.md still loads).', long: 'Use `/clear` between unrelated tasks. A long session full of stale context makes Claude slower, costlier and more error-prone. Starting fresh with a good summary often beats continuing a polluted session.' },
  'context-cmd': { term: '/context', cat: 'Context', domain: 'D5', short: 'Shows what is using your context window (system prompt, tools, MCP, memory, messages).', long: 'Run `/context` to see a breakdown of token usage. Useful for spotting a bloated CLAUDE.md or too many MCP tools.' },
  resume: { term: '--continue / --resume', aliases: ['/resume', 'resume', 'continue', '-c', '-r', 'fork_session', 'fork session'], cat: 'Session', domain: 'D1', short: 'Pick up a previous conversation: -c continues the latest, -r chooses one (or by ID).', long: '`claude -c` continues your most recent session; `claude -r` (or `/resume`) shows a picker. Sessions can be **forked** to explore an alternative from a shared starting point. **Exam nuance:** resuming is great when prior context is still valid; if files changed a lot since then, a fresh session with a summary can be more reliable than resuming stale tool results.' },
  headless: { term: 'Headless mode (-p)', aliases: ['-p', '--print', 'print mode', 'non-interactive'], cat: 'Automation', domain: 'D3', short: 'claude -p "task" runs once without the interactive UI: for scripts and CI pipelines.', long: '`claude -p` (print mode) runs a single prompt non-interactively and prints the result, then exits. Combine with `--output-format json` (or `stream-json`) for machine-readable output, `--json-schema` to enforce a shape, `--allowedTools` to pre-approve tools, and `--max-turns` to bound the run. Without `-p`, a CI job would hang waiting for input.', example: 'claude -p "Review this diff for security issues" \\\n  --output-format json \\\n  --allowedTools "Read,Grep,Glob"' },
  'output-format': { term: '--output-format', aliases: ['output format', 'stream-json', '--json-schema'], cat: 'Automation', domain: 'D3', short: 'text (default) · json (one result object) · stream-json (events as they happen).', long: 'In CI, `--output-format json` gives a parseable result (plus cost and session id). `stream-json` streams each event. `--json-schema` constrains the final answer to your schema, handy for posting structured findings as PR comments.' },
  'github-actions': { term: 'Claude Code GitHub Actions', aliases: ['github action', 'claude-code-action', 'ci', 'ci/cd'], cat: 'Automation', domain: 'D3', short: 'Run Claude Code in GitHub workflows: respond to @claude mentions, review PRs, fix issues.', long: 'Run `/install-github-app` inside Claude Code (needs repo admin rights and `gh auth login`): it installs the Claude GitHub App, stores a secret (`ANTHROPIC_API_KEY`, or `CLAUDE_CODE_OAUTH_TOKEN` from `claude setup-token` to use your subscription) and opens a PR adding the workflow. Or add `anthropics/claude-code-action@v1` yourself. Without a `prompt` it answers @claude mentions; with a `prompt` it runs automatically on events or schedules. Claude reads CLAUDE.md for project context. Good CI design: give it the context it needs (test conventions, what is already covered), avoid duplicate comments on re-runs by including prior findings, and keep permissions tight.' },
  'agent-sdk': { term: 'Claude Agent SDK', aliases: ['agent sdk', 'claude-agent-sdk', 'sdk'], cat: 'Automation', domain: 'D1', short: 'Claude Code\'s engine as a library (Python & TypeScript) for building your own agents.', long: 'The Agent SDK gives you the same agent loop, built-in tools, context management, hooks, subagents and permissions that power Claude Code, callable from code with `query()`. Use it to build custom agents (support bots, research agents, internal tools) that you host yourself.', example: 'from claude_agent_sdk import query, ClaudeAgentOptions\n\nasync for msg in query(\n    prompt="Find TODOs and summarize them",\n    options=ClaudeAgentOptions(allowed_tools=["Read", "Grep", "Glob"]),\n):\n    print(msg)', lang: 'python' },
  plugin: { term: 'Plugin', aliases: ['plugins', '/plugin', 'marketplace'], cat: 'Extending', domain: 'D3', short: 'A shareable bundle of commands, subagents, skills, hooks and MCP servers, installed with /plugin.', long: 'Plugins package your customizations so a team (or the world) can install them in one step from a **marketplace**. Run `/plugin` to browse and install.' },
  'bash-mode': { term: 'Bash mode (!)', aliases: ['!', 'bash mode', '! command'], cat: 'Shortcuts', domain: 'D3', short: 'Start input with ! to run a shell command directly; its output is added to the conversation.', long: 'Typing `! npm test` runs the command immediately (no Claude turn needed), and the output lands in context so you can say "fix those failures".' },
  mention: { term: '@ mentions', aliases: ['@', '@file', 'file mention'], cat: 'Shortcuts', domain: 'D3', short: 'Type @ to point Claude at a specific file or folder (with autocomplete).', long: '`@src/auth/login.ts why does this reject valid emails?` pulls that file straight into context. Being specific saves tokens and gets better answers than "look at the login code".' },
  'shift-tab': { term: 'Shift+Tab', aliases: ['shift tab'], cat: 'Shortcuts', domain: 'D3', short: 'Cycles permission modes: default → accept edits → plan mode (→ auto, where available).', long: 'Watch the status line under the input box: it shows which mode you are in.' },
  escape: { term: 'Esc / Esc Esc', aliases: ['esc', 'interrupt'], cat: 'Shortcuts', domain: 'D3', short: 'Esc interrupts Claude mid-task (keeps context); Esc twice opens rewind.', long: 'Interrupting early is a skill: if Claude heads the wrong way, press Esc and redirect ("stop, don\'t change the schema, only the handler"). Much cheaper than letting it finish and undoing.' },
  'trust-dialog': { term: 'Trust dialog', aliases: ['trust this folder', 'workspace trust'], cat: 'Permissions', domain: 'D3', short: 'The first time you run Claude Code in a folder it asks whether you trust the files there.', long: 'Project files (CLAUDE.md, settings, hooks, MCP config) can influence what Claude does, so Claude Code asks you to confirm you trust a folder before using them. Only trust code you know.' },
  'prompt-injection': { term: 'Prompt injection', aliases: ['injection'], cat: 'Safety', domain: 'D5', short: 'Malicious instructions hidden in content Claude reads (a web page, issue, file) trying to hijack it.', long: 'Treat external content as data, not instructions. Limit tools and permissions, keep humans in the loop for risky actions, use hooks for hard guarantees, and never give an agent more access than its task needs (least privilege).' },
  'least-privilege': { term: 'Least privilege', aliases: ['scoped tools', 'tool restriction'], cat: 'Safety', domain: 'D2', short: 'Give each agent only the tools and access its job requires.', long: 'A reviewer subagent needs Read/Grep, not Bash or Write. Fewer tools also means better tool selection: agents with a small, focused toolset (around 4–5 tools) choose more reliably than ones with 18.' },
  escalation: { term: 'Escalation / human handoff', aliases: ['handoff', 'human in the loop', 'hitl'], cat: 'Reliability', domain: 'D5', short: 'Passing a case to a human when policy, ambiguity or the customer requires it.', long: 'Escalate when the customer **explicitly asks** for a human, when policy is silent or ambiguous, or when the agent can\'t make progress. Don\'t rely on sentiment scores or the model\'s self-reported confidence. Hand off with a structured summary (customer ID, issue, what was tried, recommended action) so the human doesn\'t start from zero.' },
  'lost-in-the-middle': { term: 'Lost in the middle', aliases: ['lost-in-the-middle'], cat: 'Context', domain: 'D5', short: 'Models pay most attention to the start and end of long inputs; details in the middle can be missed.', long: 'Put key findings and instructions at the beginning (or end), use clear section headers, and trim verbose tool outputs to the fields that matter before they pile up in context.' },
  'case-facts': { term: 'Case facts block', aliases: ['persistent facts', 'scratchpad'], cat: 'Context', domain: 'D5', short: 'A short, always-included block of critical facts (IDs, amounts, dates) that survives summarization.', long: 'Summaries blur specifics ("the customer wants a refund" loses "$247.83 for order #8812 on 3 March"). Extract the transactional facts into a structured block kept in every prompt, or write them to a scratchpad file that long-running agents re-read.' },
  provenance: { term: 'Provenance / attribution', aliases: ['citations', 'source attribution'], cat: 'Reliability', domain: 'D5', short: 'Keeping track of where each claim came from (source, URL, date) through a multi-agent pipeline.', long: 'When subagents return findings, have them return structured claim → source mappings. Then the final synthesis can cite properly, and conflicting sources (e.g., two different statistics) are annotated rather than silently merged.' },
  'confidence-calibration': { term: 'Confidence calibration', aliases: ['stratified sampling', 'human review'], cat: 'Reliability', domain: 'D5', short: 'Checking that "95% confident" really means right 95% of the time, per category, before you automate.', long: 'Before reducing human review, measure accuracy per document type and per field (not just overall), using a labeled validation set and ongoing stratified sampling. A 97% overall score can hide a category that is badly wrong.' },
  'effort': { term: 'Effort', aliases: ['effort level', 'thinking', 'extended thinking', 'adaptive thinking'], cat: 'API', domain: 'D4', short: 'How hard the model thinks: low · medium · high · xhigh · max. Higher = smarter but slower and pricier.', long: 'Current Claude models use **adaptive thinking**: they decide how much to reason, and **effort** sets the overall depth and token spend. Use low for simple chat, high/xhigh for hard coding and agent work.' },
  statusline: { term: 'Status line', aliases: ['/statusline'], cat: 'Config', short: 'A customizable bar under the input showing model, mode, git branch, cost…', long: 'Configure with `/statusline`. Handy for always seeing which model and mode you\'re in.' },
  'output-style': { term: 'Output styles', aliases: ['/output-style', 'learning mode', 'explanatory'], cat: 'Config', short: 'Change how Claude Code talks to you, e.g. "Explanatory" (explains as it works) or "Learning" (asks you to write some code).', long: 'Great for beginners: the Explanatory and Learning styles turn Claude Code into a tutor while it works.' },
  worktree: { term: 'Git worktrees', aliases: ['worktree', 'worktrees', 'parallel sessions'], cat: 'Session', short: 'Several checkouts of one repo in different folders, so multiple Claude sessions can work in parallel without clashing.', long: '`git worktree add ../feature-a -b feature-a` creates a second working folder on its own branch. Run a separate Claude Code session in each.' },
  'claude-web': { term: 'Claude Code on the web', aliases: ['claude.ai/code', 'cloud sessions', 'remote'], cat: 'Surfaces', short: 'Run Claude Code in a cloud sandbox from your browser or phone; it works on a GitHub repo and pushes a branch.', long: 'Start tasks at claude.ai/code, kick off several in parallel, and review the resulting branches or PRs. Each session gets an isolated container with configurable network access and setup scripts.' },
  ide: { term: 'IDE integrations', aliases: ['vs code', 'vscode', 'jetbrains', 'extension'], cat: 'Surfaces', short: 'Claude Code extensions for VS Code (and forks) and JetBrains IDEs: inline diffs, selection context.', long: 'The IDE extension shows Claude\'s proposed edits as visual diffs, shares your current selection and open file as context, and lets you work in a side panel.' },
  'managed-agents': { term: 'Claude Managed Agents', aliases: ['managed agents'], cat: 'Platform', domain: 'D1', short: 'Anthropic-hosted agents: Anthropic runs the agent loop and a sandbox container per session (beta).', long: 'Instead of hosting your own agent loop, you define a versioned agent config (model, system prompt, tools, MCP, skills) once and start sessions against it in an environment (cloud container or your own self-hosted sandbox). Anthropic runs the loop. Extras: vaults for credentials, memory stores, outcomes graded by a rubric, multi-agent workflows, scheduled deployments and session budgets. Beta; session runtime is billed on top of tokens.' },
  'tool-search': { term: 'Tool search', aliases: ['deferred tools', 'defer_loading'], cat: 'Tools', domain: 'D2', short: 'Let Claude search a big tool catalog and load only the tools it needs, instead of loading all of them up front.', long: 'With dozens or hundreds of tools (many MCP servers), loading every definition wastes context and hurts selection. Mark tools as deferred and give Claude a search tool; it discovers and loads the relevant ones on demand.' },
  'session': { term: 'Session', aliases: ['conversation'], cat: 'Session', short: 'One continuous Claude Code conversation, saved so you can resume it.', long: 'Each time you run `claude` you start a session. Sessions are saved locally; use `--continue`, `--resume` or `/resume` to return to one.' },
  'interview': { term: 'Interview pattern', aliases: ['ask me questions'], cat: 'Workflow', domain: 'D3', short: 'Ask Claude to interview you with clarifying questions before it writes code, for unfamiliar or fuzzy tasks.', long: '"Before implementing, ask me up to 5 questions about requirements and edge cases." This surfaces design considerations (cache invalidation, error handling, auth) you might not have thought of.' },
  'tdd': { term: 'Test-driven iteration', aliases: ['tdd', 'tests first'], cat: 'Workflow', domain: 'D3', short: 'Write (or have Claude write) failing tests first, then let Claude iterate until they pass.', long: 'Tests give Claude an objective target and a way to verify its own work. Sharing the actual failing output each round is more effective than describing the problem in prose.' },
  'explore-plan-code': { term: 'Explore → Plan → Code → Commit', aliases: ['explore plan code commit'], cat: 'Workflow', domain: 'D3', short: 'The recommended Claude Code workflow: research first, make a plan, then implement and verify, then commit.', long: '1) **Explore**: have Claude read the relevant files (no code yet). 2) **Plan**: ask for a plan (plan mode); review it. 3) **Code**: implement and verify with tests. 4) **Commit**: have Claude commit and open a PR. Skipping steps 1–2 is the most common cause of wasted work on non-trivial tasks.' },

  // --------------------------------------------- connect & automate
  'computer-use': { term: 'Computer use', aliases: ['computer toolset', 'computer_toolset_20260801'], cat: 'Automation', domain: 'D2', short: 'Claude controls a computer through screenshots plus mouse and keyboard actions that your program performs.', long: 'Your program sends screenshots; Claude replies with actions like `left_click` at `[x, y]`, `type` or `key`; your program performs them and sends a new screenshot. On the current API it is enabled with one tool entry: `{"type": "computer_toolset_20260801"}` (17 actions). Coordinates are in the pixels of the screenshots you send. Always run it in a VM or container with a human approving consequential actions.', example: 'tools=[{"type": "computer_toolset_20260801"}]', lang: 'python', analogy: 'remote-controlling a PC by looking at photos of its screen.' },
  'browser-toolset': { term: 'Browser use toolset', aliases: ['browser_toolset_20260801', 'browser use'], cat: 'Automation', domain: 'D2', short: 'API toolset for acting inside web pages: navigate, read_page, click by element ref or coordinate, type, tabs.', long: 'Declared as `{"type": "browser_toolset_20260801"}`. Claude can target elements by reference (from `read_page`/`find`) instead of guessing pixels, and manage tabs. Your program runs the browser (e.g. Chromium via Playwright). Risky members (`javascript_exec`, `file_upload`, `read_console`, `read_network`) are off by default.' },
  'accessibility-tree': { term: 'Accessibility tree', aliases: ['snapshot', 'page snapshot', 'aria snapshot', 'browser_snapshot'], cat: 'Automation', domain: 'D2', short: 'The structured outline of a page (roles, names, states) that screen readers and browser agents use to find elements.', long: 'Instead of pixels, a browser agent reads lines like `button "Create account" [ref=e11]` and clicks that ref. It is faster, cheaper and survives layout changes. Playwright MCP and the browser toolset both rely on it.', example: '- textbox "Email" [ref=e5]\n- button "Create account" [ref=e11]', lang: 'md' },
  'playwright-mcp': { term: 'Playwright MCP', aliases: ['@playwright/mcp', 'playwright'], cat: 'Automation', domain: 'D2', short: "Microsoft's MCP server that gives Claude a real browser: navigate, snapshot, click, type, screenshot.", long: 'Add it to Claude Code with `claude mcp add playwright npx @playwright/mcp@latest`. Claude calls tools like `browser_navigate`, `browser_snapshot`, `browser_click` (with `element` + `target` ref) and `browser_type`. Flags such as `--headless` and `--browser msedge` go after the package name.', example: 'claude mcp add playwright npx @playwright/mcp@latest' },
  'claude-in-chrome': { term: 'Claude in Chrome', aliases: ['chrome extension', '--chrome', '/chrome'], cat: 'Automation', short: 'A browser extension that lets Claude act in your real Chrome/Edge; Claude Code connects to it with `claude --chrome`.', long: 'Good for sites you are already logged in to: testing web apps, filling forms, extracting data. It pauses at logins and CAPTCHAs. It needs a Claude plan sign-in (not an API key). Because it uses your real accounts, review its actions.' },
  'mcp-stdio': { term: 'stdio transport', aliases: ['stdio', 'local server'], cat: 'Extending', domain: 'D2', short: 'MCP over standard input/output: the host starts the server as a local program and talks to it through stdin/stdout.', long: 'The usual choice for servers that act on your own computer. Because stdout carries the protocol messages, a stdio server must log to stderr, never print() debug text to stdout. Remote servers use Streamable HTTP instead.' },
  'mcp-connector': { term: 'MCP connector (API)', aliases: ['mcp_servers', 'mcp_toolset'], cat: 'API', domain: 'D2', short: 'Lets the Messages API call tools on a remote MCP server for you: `mcp_servers` + an `mcp_toolset` tool entry.', long: 'Beta (`mcp-client-2025-11-20`). Anthropic opens the MCP connection server-side, so your app needs no MCP client. Both parts are required; the toolset references the server by name. For local stdio servers, use the MCP client in your own code instead.', example: 'mcp_servers=[{"type": "url", "url": "https://mcp.example.com/mcp", "name": "example"}],\ntools=[{"type": "mcp_toolset", "mcp_server_name": "example"}]', lang: 'python' },
  'mcp-inspector': { term: 'MCP Inspector', aliases: ['inspector', 'mcp dev'], cat: 'Extending', domain: 'D2', short: 'A browser-based tester for MCP servers: list tools, call them with inputs, see raw results.', long: 'Run `mcp dev server.py` (Python SDK) or `npx @modelcontextprotocol/inspector` for any server. Always test a new server here before connecting it to Claude; it shows exactly what Claude will see.' },
  'mcp-host': { term: 'MCP host / client / server', aliases: ['host', 'mcp client'], cat: 'Extending', domain: 'D2', short: 'Host = the AI app (Claude Code); client = its connection to one server; server = the program exposing tools/resources/prompts.', long: 'One host can open many clients, one per server. Servers offer three primitives: tools (model-controlled), resources (app/user-attached data) and prompts (user-invoked templates).' },
  'tool-runner': { term: 'Tool Runner', aliases: ['beta_tool', 'tool_runner'], cat: 'API', domain: 'D1', short: 'An SDK helper that runs the agent loop for you: you write tool functions, it calls them and feeds results back.', long: 'In Python: decorate functions with `@beta_tool` and call `client.beta.messages.tool_runner(...)`. The docstring and type hints become the tool description and schema. Write the loop yourself only when you need custom control flow.' },
  'server-tools': { term: 'Server tools', aliases: ['web_search', 'web_fetch', 'code execution', 'code_execution'], cat: 'API', domain: 'D2', short: 'Tools Anthropic runs for you (web search, web fetch, code execution, tool search): declare them and results arrive in the same response.', long: 'Unlike client tools, you don\'t execute anything: e.g. `{"type": "web_search_20260209", "name": "web_search"}`. Errors come back as result blocks, not exceptions.' },
  sandbox: { term: 'Sandbox / VM', aliases: ['vm', 'virtual machine', 'container'], cat: 'Safety', domain: 'D5', short: 'An isolated computer (virtual machine or container) where an agent can act without risking your real files and accounts.', long: 'Computer use and autonomous agents should run in a sandbox with minimal privileges, no unnecessary credentials, and an internet allowlist. Anthropic\'s computer-use demo runs a whole desktop inside Docker for this reason.' },
  'claude-desktop-config': { term: 'claude_desktop_config.json', aliases: ['desktop config', 'claude desktop config', 'desktop extensions'], cat: 'Extending', domain: 'D2', short: 'Claude Desktop\'s MCP config file (Settings → Developer → Edit Config); or install packaged servers as Desktop Extensions.', long: 'Lists servers under `mcpServers` with `command`, `args` and optional `env`. Windows: `%APPDATA%\\Claude\\claude_desktop_config.json`; macOS: `~/Library/Application Support/Claude/`. Restart Claude Desktop after editing. Desktop Extensions install servers with one click.', example: '{ "mcpServers": { "playwright": { "command": "npx", "args": ["@playwright/mcp@latest"] } } }', lang: 'json' },

  // --------------------------------------------------- GitHub & git
  commit: { term: 'Commit', aliases: ['commits', 'git commit'], cat: 'GitHub', domain: 'D3', short: 'A saved snapshot of your project with a message explaining the change.', long: 'Stage changes with `git add`, then save them with `git commit -m "message"`. Each commit has an ID (like `4f2a9c1`), an author, a time and a parent commit, forming the project history. Small, focused commits with clear messages are easy to review and undo. Claude Code writes good messages from the actual diff.', example: 'git add src/cart.js\ngit commit -m "fix: cap discounts at 0-100%"', analogy: 'a save point in a video game, with a note about what you just did.' },
  branch: { term: 'Branch', aliases: ['branches', 'git branch', 'feature branch'], cat: 'GitHub', domain: 'D3', short: 'A separate line of work; changes on a branch don\'t affect main until merged.', long: 'Create one with `git switch -c fix/cart`. Work and commit there, then open a pull request to merge it into `main`. Branches let you (and parallel Claude sessions) try things safely.', example: 'git switch -c feature/search\ngit switch main', analogy: 'a photocopy of the plan you can scribble on without touching the original.' },
  'pull-request': { term: 'Pull request (PR)', aliases: ['pr', 'pull requests', 'prs', 'github flow'], cat: 'GitHub', domain: 'D3', short: 'A proposal to merge a branch into another, with the diff, discussion, reviews and automated checks.', long: 'Push a branch, then open a PR (`gh pr create`). Reviewers comment on lines, CI runs, and when everything passes it is merged (merge commit, squash or rebase). Writing "Fixes #38" in the description auto-closes that issue on merge. The GitHub flow is: branch, commit, push, PR, review, merge.', example: 'gh pr create --fill\ngh pr merge 43 --squash --delete-branch' },
  'gh-issue': { term: 'Issue', aliases: ['issues', 'github issue', 'gh issue'], cat: 'GitHub', short: 'A tracked task, bug or idea in a GitHub repo, with labels, assignees and discussion.', long: 'Issues are your to-do list. Reference them as #38, link PRs with closing keywords, organize them in GitHub Projects. A clear issue is also a great prompt for Claude ("fix issue #38") or for @claude via the GitHub Action.' },
  'github-actions-ci': { term: 'GitHub Actions (CI)', aliases: ['workflow', 'workflows', 'ci', 'continuous integration', 'status checks'], cat: 'GitHub', domain: 'D3', short: 'GitHub\'s automation: YAML workflows in .github/workflows that run jobs on events like push and pull_request.', long: 'A workflow has triggers (`on:`), jobs that run on fresh VMs (`runs-on:`), and steps that either `uses:` a ready-made action or `run:` a command. Use it to run tests on every PR (status checks), build releases, or run Claude. Secrets are stored encrypted and referenced as `${{ secrets.NAME }}`.', example: 'on: [pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - run: npm test', lang: 'yaml' },
  pat: { term: 'Personal access token (PAT)', aliases: ['token', 'fine-grained token', 'github token'], cat: 'GitHub', domain: 'D5', short: 'A password-like key that lets tools act on GitHub as you. Prefer fine-grained tokens with minimal scope and an expiry.', long: 'Create in GitHub → Settings → Developer settings. Fine-grained tokens can be limited to specific repositories and permissions, which is least privilege for tools like the GitHub MCP server. Never commit a token; if one leaks, revoke it immediately.' },
  'git-undo': { term: 'Undoing in git', aliases: ['revert', 'git revert', 'reset', 'git reset', 'restore', 'reflog'], cat: 'GitHub', short: 'restore (discard edits), revert (undo a pushed commit safely), reset --soft (un-commit, keep changes), reflog (find lost commits).', long: 'Use `git revert` for anything already pushed: it adds an "undo" commit instead of rewriting history. Avoid `git reset --hard` and force-pushing on shared branches. `git reflog` lists where your branches have been, so you can recover almost anything.' },
  'merge-conflict': { term: 'Merge conflict', aliases: ['conflict', 'conflicts'], cat: 'GitHub', short: 'When two branches changed the same lines, git asks you to choose; it marks them with <<<<<<< ======= >>>>>>>.', long: 'Edit the file to the correct final version, remove the markers, then `git add` and `git commit`. Claude Code can resolve conflicts and explain its choices; always review and run the tests afterwards.', example: '<<<<<<< HEAD\nconst MAX = 100;\n=======\nconst MAX = 90;\n>>>>>>> sale', lang: 'md' },
  'branch-protection': { term: 'Branch protection / rulesets', aliases: ['rulesets', 'protected branch', 'required checks'], cat: 'GitHub', domain: 'D3', short: 'Repo rules that stop direct pushes to main and require PRs, reviews and passing checks before merging.', long: 'Set in Settings → Rules → Rulesets. Essential when AI writes code: nothing reaches main without tests passing and a review. Pair with CODEOWNERS to auto-request the right reviewers.' },
  'gh-cli': { term: 'GitHub CLI (gh)', aliases: ['gh', 'github cli'], cat: 'GitHub', short: 'GitHub in your terminal: repos, issues, PRs, Actions runs and the API, so Claude Code can use them too.', long: 'Install it (`winget install GitHub.cli`), sign in with `gh auth login`, then Claude can run `gh issue view 38`, `gh pr create`, `gh pr checks`, `gh run view --log-failed`. `/install-github-app` also needs it.', example: 'gh auth login\ngh issue list\ngh pr create --fill\ngh run view --log-failed' },
  'github-mcp': { term: 'GitHub MCP server', aliases: ['github-mcp-server', 'github mcp'], cat: 'GitHub', domain: 'D2', short: 'GitHub\'s official MCP server (remote at api.githubcopilot.com/mcp, or local via Docker) with toolsets for repos, issues, PRs, Actions and more.', long: 'Add it to Claude Code with a fine-grained token, or connect it in Claude Desktop / claude.ai. Choose toolsets with --toolsets and use --read-only for safe exploration. The old npm package @modelcontextprotocol/server-github is deprecated.', example: 'claude mcp add --transport http github https://api.githubcopilot.com/mcp -H "Authorization: Bearer YOUR_GITHUB_PAT"' },

  // ------------------------------------------- Claude apps & agent hosting
  cowork: { term: 'Cowork', aliases: ['claude cowork', 'co work', 'co-work'], cat: 'Surfaces', short: 'Claude doing multi-step knowledge work for you (files, documents, spreadsheets, research, recurring tasks) without code.', long: 'Cowork plans, acts with tools and checks its work, like Claude Code but for non-coding tasks. Sessions run in the cloud; the Claude desktop app adds access to folders you connect, a browser and computer use. Permission modes: Manual, Auto, Skip; deleting always asks. Recurring work uses scheduled tasks (/schedule). It is being merged into the main Claude chat experience.' },
  'claude-project': { term: 'Project (Claude chat)', aliases: ['projects', 'project knowledge', 'claude project'], cat: 'Surfaces', domain: 'D5', short: 'A chat workspace with its own uploaded knowledge and instructions that every chat inside it uses.', long: 'Create a project, add instructions (how Claude should behave) and knowledge files (docs, notes, style guides). Large knowledge is retrieved as needed (RAG). Team/Enterprise can share projects. It is the chat-app equivalent of CLAUDE.md.' },
  rag: { term: 'RAG (retrieval-augmented generation)', aliases: ['retrieval', 'retrieval augmented generation', 'embeddings'], cat: 'Context', domain: 'D5', short: 'Finding the most relevant pieces of a large knowledge base and giving only those to the model for each question.', long: 'Instead of stuffing every document into the context window, a retrieval step (keyword or embedding search) picks the relevant chunks. Claude Projects do this automatically for large knowledge; in your own apps you build it with a search index.' },
  'self-hosted-sandbox': { term: 'Self-hosted sandbox', aliases: ['self_hosted', 'environment worker', 'environmentworker'], cat: 'Platform', domain: 'D5', short: 'A Managed Agents environment where Anthropic runs the agent loop but your own worker runs tools and files inside your network.', long: 'Create the environment with config type self_hosted, generate an environment key, run an EnvironmentWorker (Python/TypeScript/Go) or `ant beta:worker poll`. Connectivity is outbound-only. Tool inputs and outputs still reach Anthropic so the model can see them.' },

  // ------------------------------------------------- context engineering
  'context-engineering': { term: 'Context engineering', aliases: ['context management'], cat: 'Context', domain: 'D5', short: 'Deciding everything the model sees each turn: instructions, documents, tools, memories, history, and in what order and size.', long: 'The goal is the smallest set of high-signal tokens that makes the right answer likely. Four moves: write context outside the window (files, memory), select only what\'s relevant (retrieval, @-mentions), compress (compaction, trimming), and isolate messy work (subagents).' },
  'context-rot': { term: 'Context rot', aliases: ['context degradation', 'attention budget'], cat: 'Context', domain: 'D5', short: 'Answer quality degrading as the context grows long or cluttered with stale, irrelevant or contradictory content.', long: 'Attention is finite: details get lost (especially in the middle), old tool results mislead, and costs rise. Counter it with focused context, trimming, context editing, compaction and fresh sessions.' },
  'just-in-time': { term: 'Just-in-time context', aliases: ['agentic search', 'just in time'], cat: 'Context', domain: 'D5', short: 'Giving the agent references (paths, IDs, URLs) and tools to fetch details when needed, instead of pre-loading everything.', long: 'Claude Code works this way: Glob and Grep to find candidates, then Read only the files that matter. It keeps context small and always current, at the cost of a few extra tool calls.' },
  'context-editing': { term: 'Context editing', aliases: ['clear_tool_uses', 'clear tool uses'], cat: 'API', domain: 'D5', short: 'An API feature (beta) that removes stale tool results or thinking blocks from the conversation before the model sees it.', long: 'Configure context_management.edits with clear_tool_uses_20250919 (optionally clearing tool inputs too) or clear_thinking_20251015, using the context-management-2025-06-27 beta. It prunes rather than summarizes, unlike compaction.' },
  'memory-tool': { term: 'Memory tool', aliases: ['memory_20250818', '/memories'], cat: 'API', domain: 'D5', short: 'A client-side tool that lets Claude read and write files in a /memories directory your app stores, for memory across sessions.', long: 'Declare {"type": "memory_20250818", "name": "memory"}. Claude uses view, create, str_replace, insert, delete and rename; your code implements the storage (the Python SDK offers BetaAbstractMemoryTool). Keep memories per-user and never store secrets.' },
  'contextual-retrieval': { term: 'Contextual retrieval', aliases: ['contextual embeddings', 'contextual bm25'], cat: 'Context', domain: 'D5', short: 'Prepending a short generated description of each chunk\'s place in its document before indexing, so retrieval finds it more reliably.', long: 'Anthropic\'s technique for RAG: Claude writes one or two sentences situating each chunk; both the embedding index and the BM25 index use the enriched chunk. Combined with hybrid search and reranking it substantially reduces failed retrievals. Prompt caching keeps the preprocessing affordable.' },
};
